public class Graph{private final java.util.List<java.util.Set<Integer>>neighbors;public Graph(int n){neighbors=new java.util.ArrayList<>();for(int i=0;i<n;i++)neighbors.add(new java.util.HashSet<>());}public void add(int a,int b){neighbors.get(a).add(b);neighbors.get(b).add(a);}public void remove(int a,int b){neighbors.get(a).remove(b);neighbors.get(b).remove(a);}public boolean edge(int a,int b){return neighbors.get(a).contains(b);}public java.util.Set<Integer>neighbors(int v){return new java.util.HashSet<>(neighbors.get(v));}}
